function pal(map){return (mt,c)=>{let v;if(c&&map['#'+c.name]!==undefined)v=map['#'+c.name];else v=map[mt.name];if(v===undefined)v=map['*'];if(v===undefined){mt.roughness=Math.max(mt.roughness,.7);return;}
 if(v===null){c.visible=false;return;}if(typeof v==='number')v={c:v};mt.map=null;mt.vertexColors=false;mt.color.setHex(v.c).convertSRGBToLinear();mt.roughness=v.r!=null?v.r:.88;mt.metalness=v.m!=null?v.m:.05;if(v.e){mt.emissive=new THREE.Color(v.e).convertSRGBToLinear();mt.emissiveIntensity=v.ei||1;}};}
