let camDist=15.5,camYaw=Math.PI*.25;const camPitch=THREE.MathUtils.degToRad(54);let camFocus=new THREE.Vector3();let cineZoom=0;
function updCamera(dt){if(CAMOV){camera.position.lerp(CAMOV.p,Math.min(1,dt*3));camera.lookAt(CAMOV.l);return;}const d=camDist*(1-cineZoom*.38);camFocus.lerp(P.pos,1-Math.pow(.002,dt));
 const off=new THREE.Vector3(Math.sin(camYaw)*Math.cos(camPitch)*d,Math.sin(camPitch)*d,Math.cos(camYaw)*Math.cos(camPitch)*d);
 camera.position.copy(camFocus).add(off);if(shakeA>0){camera.position.x+=(Math.random()-.5)*shakeA;camera.position.y+=(Math.random()-.5)*shakeA;shakeA=Math.max(0,shakeA-dt*2.5);}
 camera.lookAt(camFocus.x,camFocus.y+.8,camFocus.z);
 sun.position.set(camFocus.x-18,22,camFocus.z-10);sun.target.position.copy(camFocus);
 // occluder fade
 const dir=new THREE.Vector3().subVectors(P.pos.clone().setY(TOP+1),camera.position);const len=dir.length();dir.normalize();ray.set(camera.position,dir);ray.far=len;
 const hits=ray.intersectObjects(DOMES.map(d=>d.mesh),false);DOMES.forEach(dm=>{const hit=hits.some(h=>h.object===dm.mesh);dm.mat.opacity+=((hit?.28:1)-dm.mat.opacity)*Math.min(1,dt*6);dm.mat.depthWrite=dm.mat.opacity>.95;});}
// ================= MOVEMENT / COLLISION =================
function walkable(x,z){for(const [rx,rz,w,d] of WALK){if(Math.abs(x-rx)<=w/2-.25&&Math.abs(z-rz)<=d/2-.25)return true;}return false;}
function collide(p,r){for(const d of DOMES){const dx=p.x-d.x,dz=p.z-d.z,l=Math.hypot(dx,dz),m=d.r+r;if(l<m&&l>0){p.x=d.x+dx/l*m;p.z=d.z+dz/l*m;}}
 for(const o of OBST){const dx=p.x-o.x,dz=p.z-o.z,l=Math.hypot(dx,dz),m=o.r+r;if(l<m&&l>0){p.x=o.x+dx/l*m;p.z=o.z+dz/l*m;}}}
function tryMove(obj,nx,nz,r){const ox=obj.x,oz=obj.z;const p={x:nx,z:nz};collide(p,r);if(walkable(p.x,p.z)){obj.x=p.x;obj.z=p.z;return true;}if(walkable(p.x,oz)){obj.x=p.x;return true;}if(walkable(ox,p.z)){obj.z=p.z;return true;}return false;}
let moveTarget=null,targetEnemy=null;
