function nearestEnemy(range){let b=null,bd=range;for(const e of ENEMIES){if(e.dead)continue;const d=Math.hypot(e.x-P.pos.x,e.z-P.pos.z);if(d<bd){bd=d;b=e;}}return b;}
function attack(e){if(P.atkCd>0||C1.on)return;P.face=Math.atan2(e.x-P.pos.x,e.z-P.pos.z);P.combo=P.comboT>0?(P.combo+1)%3:0;P.comboT=.9;P.atkCd=P.combo===2?.62:.42;pu.attacking=.34;SFX.swing();slash();if(TRAIL){try{TRAIL.reset();trailT=.32;}catch(err){}}if(PM){PM.once(P.combo===2?'Sword_Slash':'Sword_Slash',P.combo===2?1.6:2.1);if(PM.blade)PM.blade.forEach(m=>m.emissiveIntensity=3);}
 setTimeout(()=>{if(e.dead)return;const d=Math.hypot(e.x-P.pos.x,e.z-P.pos.z);if(d>2.4)return;const crit=Math.random()<.12;let dmg=(P.combo===2?20:12)+P.lvl*2+(Math.random()*4|0);if(crit)dmg*=2;
  hurtEnemy(e,dmg,crit,P.combo===2?7:2.5);},140);}
function hurtEnemy(e,dmg,crit,kb){if(e.type==='sent'){kb=0;if(e.shieldT<=0){dmgText(new THREE.Vector3(e.x,TOP+1,e.z),'KALKAN','');tone(1800,.08,'square',.05);if(!e.hinted||performance.now()-e.hinted>6000){e.hinted=performance.now();toast(isTouch?'Kalkan açık — EMP düğmesine bas':'Kalkan açık — 1: Aşırı Yük',true,2);}return;}}
e.hp-=dmg;e.flash=.12;e.aggro=true;const a=Math.atan2(e.x-P.pos.x,e.z-P.pos.z);e.kx=Math.sin(a)*kb;e.kz=Math.cos(a)*kb;SFX.hit();shakeA=Math.max(shakeA,crit?.35:.15);
 dmgText(new THREE.Vector3(e.x,TOP,e.z),crit?dmg+'!':String(dmg),crit?'c':'');burst(new THREE.Vector3(e.x,TOP+.9,e.z),0xffc070,10,4,.4,.08);
 if(e.state==='wind'&&kb>5){e.state='chase';e.ring.material.opacity=0;if(e.ind)e.ind.stop();}
 if(e.type==='sur'&&e.mdl&&e.lock<=0&&!e.officer){e.mdl.once('HitRecieve',1.6);e.lock=.3;}
 if(e.officer){if(e.hp<=0)e.hp=1;c3OffHurt(e);}
 if(e.hp<=0)killEnemy(e);}
function killEnemy(e){e.dead=true;e.deathT=e.mdl?1.1:0;if(e.mdl)e.mdl.play('Death',.08,true);SFX.die();e.ring.material.opacity=0;burst(new THREE.Vector3(e.x,TOP+.7,e.z),0x9a948a,60,3,1.4,.14);burst(new THREE.Vector3(e.x,TOP+.9,e.z),0xff3a1a,12,2,.6,.1);e.dissolve=1;gainXP(e.boss?120:25);
 if(Math.random()<.25)dropMed(e.x,e.z);onEnemyDead(e);}
function dropMed(x,z){medkit(x,z);}
function gainXP(n){P.xp+=n;const need=80+P.lvl*40;if(P.xp>=need){P.xp-=need;P.lvl++;P.max+=12;P.hp=P.max;P.ymax+=5;SFX.lvl();toast('SEVİYE '+P.lvl);}}
function hurtPlayer(n){if(P.inv>0||P.dead||dlgActive)return;P.hp-=n;P.inv=.35;SFX.hurt();shakeA=.4;dmgText(P.pos,'-'+n,'p');$('hurt').style.opacity=1;setTimeout(()=>$('hurt').style.opacity=0,220);if(P.hp<=0)playerDie();}
function useEmp(){if(!playing||dlgActive||!empUnlocked||C1.on)return;if(P.empCd>0||P.yuva<35){toast(P.yuva<35?'YUVA YETERSİZ':'',true,1);return;}P.yuva-=35;P.empCd=4;SFX.emp();shakeA=.3;
 shock(P.pos,0x55f0ff,6.5);vfx('shockwave',P.pos.x,TOP,P.pos.z,{color:'#7fe9ff',size:2.2});burst(P.pos.clone().setY(TOP+1),0x55f0ff,50,7,.6,.1);neckL.intensity=6;canvas.classList.add('breath');setTimeout(()=>canvas.classList.remove('breath'),90);
 for(const e of ENEMIES){if(e.dead)continue;const d=Math.hypot(e.x-P.pos.x,e.z-P.pos.z);if(e.type==='sent'){if(d<7){e.shieldT=6;toast('KALKAN ÇÖKTÜ',false,1.5);hurtEnemy(e,14+P.lvl*2,false,0);}continue;}if(d<5.2){e.stun=2.6;e.state='chase';e.ring.material.opacity=0;hurtEnemy(e,22+P.lvl*3,false,6);}}}
function playerDie(){P.dead=true;playing=false;toast('KÜL SENİ DE YUTTU',true,2.5);setFade(1);setTimeout(()=>{P.hp=P.max;P.yuva=P.ymax;P.pos.copy(P.checkpoint);P.dead=false;ENEMIES.forEach(e=>{if(!e.dead){e.x=e.hx;e.z=e.hz;e.state='idle';e.aggro=false;e.hp=e.max;}});setFade(0);playing=true;},2200);}
