// ================= ENEMY AI =================
function updEnemies(dt,frozen){for(const e of ENEMIES){if(e.ind){e.ind.update(dt);if(e.dead&&!e.indOff){e.indOff=1;e.ind.stop();}if(e.stun>0&&e.state!=='wind'&&e.ind.progress>0&&e.ind.progress<1&&!e.indStop){e.indStop=1;e.ind.stop();}}
 if(e.dead){if(e.deathT>0){e.deathT-=dt;continue;}if(e.dissolve>0){e.dissolve-=dt*1.3;if(!e.mdl)e.g.scale.setScalar(Math.max(.01,e.dissolve)*(e.boss?1.6:1));e.g.position.y=TOP-(1-e.dissolve)*.6;if(e.dissolve<=0){scene.remove(e.g);scene.remove(e.ring);if(e.mdl)e.mdl.on=false;}}continue;}
 if(e.type==='sent'){updSent(e,dt);continue;}if(e.type==='sur'){updSur(e,dt);continue;}
 e.flash-=dt;if(e.mdl)e.mdl.mats.forEach(m=>{if(m.emissive&&!/Eye/i.test(m.name))m.emissiveIntensity=e.flash>0?1.6:0;});else e.g.children[0].material=e.flash>0?M.amber:enemyBody;
 if(frozen||dlgActive||!playing){continue;}
 const dx=P.pos.x-e.x,dz=P.pos.z-e.z,dist=Math.hypot(dx,dz);
 if(e.kx||e.kz){tryMove(e,e.x+e.kx*dt,e.z+e.kz*dt,.45);e.kx*=Math.pow(.02,dt);e.kz*=Math.pow(.02,dt);if(Math.abs(e.kx)+Math.abs(e.kz)<.1)e.kx=e.kz=0;}
 if(e.stun>0){e.stun-=dt;e.head.rotation.z=Math.sin(e.stun*20)*.25;if(e.mdl){e.mdl.play('Idle_HitReact_Left',.1);e.g.rotation.z=Math.sin(e.stun*25)*.05;}e.g.position.set(e.x,TOP,e.z);continue;}e.head.rotation.z=0;
 let spd=0;
 if(e.state==='idle'){e.t-=dt;if(e.t<0){e.t=2+Math.random()*3;e.wx=e.hx+(Math.random()-.5)*4;e.wz=e.hz+(Math.random()-.5)*4;}
  const wx=e.wx-e.x,wz=e.wz-e.z,wl=Math.hypot(wx,wz);if(wl>.3){e.face=Math.atan2(wx,wz);spd=1.2;tryMove(e,e.x+wx/wl*spd*dt,e.z+wz/wl*spd*dt,.45);}
  if((dist<8.5||e.aggro)&&!P.dead&&!e.passive){e.state='chase';SFX.growl();}}
 else if(e.state==='chase'){e.face=Math.atan2(dx,dz);if(dist>e.reach*.95){spd=e.speed;
  // separation
  let sx=0,sz=0;for(const o of ENEMIES){if(o===e||o.dead)continue;const ox=e.x-o.x,oz=e.z-o.z,ol=Math.hypot(ox,oz);if(ol<1.3&&ol>0){sx+=ox/ol;sz+=oz/ol;}}
  tryMove(e,e.x+(dx/dist+sx*.6)*spd*dt,e.z+(dz/dist+sz*.6)*spd*dt,.45);}
  else{e.state='wind';e.t=e.boss?.75:.6;e.lx=P.pos.x;e.lz=P.pos.z;e.ring.position.set(e.lx,TOP+.04,e.lz);if(e.ind){e.indStop=0;e.ind.reset();e.ind.group.position.set(e.lx,TOP+.02,e.lz);e.ind.setProgress(0);}}
  if(dist>22&&!e.boss){e.state='idle';e.aggro=false;}}
 else if(e.state==='wind'){e.t-=dt;const k=1-e.t/(e.boss?.75:.6);const rr=e.boss?2:1.3;e.ring.scale.set(rr*(.4+k*.6),1,rr*(.4+k*.6));e.ring.material.opacity=.35+k*.55;if(e.ind)e.ind.setProgress(Math.min(.98,k));e.face=Math.atan2(e.lx-e.x,e.lz-e.z);e.head.position.z=.7-k*.15;
  if(e.t<=0){e.state='lunge';e.t=.22;e.head.position.z=.7;}}
 else if(e.state==='lunge'){e.t-=dt;const lx=e.lx-e.x,lz=e.lz-e.z,ll=Math.hypot(lx,lz);if(ll>.5)tryMove(e,e.x+lx/ll*12*dt,e.z+lz/ll*12*dt,.45);
  if(e.t<=0){const rr=e.boss?2:1.3;if(e.ind)e.ind.setProgress(1);if(Math.hypot(P.pos.x-e.lx,P.pos.z-e.lz)<rr+.2)hurtPlayer(e.dmg+(Math.random()*4|0));e.ring.material.opacity=0;e.state='rest';e.t=e.boss?.6:.8;}}
 else if(e.state==='rest'){e.t-=dt;if(e.t<=0)e.state='chase';}
 // anim
 if(e.mdl){e.g.rotation.z=0;e.mdl.play(e.state==='wind'?'Idle_2_HeadLow':e.state==='lunge'?'Attack':spd>2.5?'Gallop':spd>0?'Walk':'Idle',.15);const ga=e.mdl.acts.Gallop;if(ga)ga.timeScale=spd/e.speed*1.1;}
 e.ph+=dt*(spd>2?14:spd>0?6:0);e.legs.forEach((l,i)=>l.rotation.x=Math.sin(e.ph+(i%2?Math.PI:0)+(i>1?Math.PI/2:0))*(spd>0?.6:0));
 const cur=e.g.rotation.y;let df=e.face-cur;while(df>Math.PI)df-=Math.PI*2;while(df<-Math.PI)df+=Math.PI*2;e.g.rotation.y=cur+df*Math.min(1,dt*10);
 e.g.position.set(e.x,TOP+(e.state==='lunge'?.25:0),e.z);}}
