function c1fig(key,x,z,o){o=o||{};const r=makeModel(key,{scale:o.scale||1,mat:pal(o.pal||PAL[key]||{})});if(!r)return null;const g=new THREE.Group();g.add(r.wrap);g.position.set(x,TOP+(o.dy||0),z);g.rotation.y=o.face||0;(o.parent||scene).add(g);r.g=g;r.play(o.anim||'Idle',0);r.mixer.update(Math.random()*2);C1.obj.push(r);return r;}
