function updMov(dt){for(let i=C1.mov.length-1;i>=0;i--){const m=C1.mov[i];const g=m.r.g;const p=m.pts[0];if(!p){m.r.play('Idle',.2);C1.mov.splice(i,1);m.cb&&m.cb();continue;}
 const dx=p[0]-g.position.x,dz=p[1]-g.position.z,d=Math.hypot(dx,dz);m.r.play(m.anim,.2);if(d<.15){m.pts.shift();continue;}const s=Math.min(d,m.spd*dt);g.position.x+=dx/d*s;g.position.z+=dz/d*s;g.rotation.y=Math.atan2(dx,dz);}}
