 cv.addEventListener('pointerdown',e=>{drag=true;const r=cv.getBoundingClientRect();setV((e.clientX-r.left)/r.width);});addEventListener('pointerup',()=>drag=false);cv.addEventListener('pointermove',e=>{if(!drag)return;const r=cv.getBoundingClientRect();setV((e.clientX-r.left)/r.width);});
