  for(let x=0;x<560;x++){const n=(Math.random()-.5)*60*(1-q);const s=Math.sin(x*.09+S.t*30)*Math.max(0,Math.sin(x*.023+S.t*8))*55*q;const y=75+n+s;x?g.lineTo(x,y):g.moveTo(x,y);}g.stroke();
