 const bs=[...o.querySelectorAll('button')],seqEl=o.querySelector('#seq'),al=o.querySelector('#al');const FR=[330,440,550,660];let round=0,seq=[],inp=[],listen=false,miss=0;const LEN=[3,4,5];
