  const nr=C1.nurF&&C1.nurF.g.position;if(nr&&near(nr.x,nr.z,2.2)){if(s==='c1nur')nurMorning();else if(s==='c1kids'){say([D('Nur Teyze','Çocukları kapıdan uzak tut, oğlum. Ben buradayım.')]);}else if(s==='c1tea')teaScene();else say([D('Nur Teyze','Git, Deniz. Rüzgâr dönmeden.')]);return true;}
  if(C1.semaF&&near(C1.semaF.g.position.x,C1.semaF.g.position.z,1.7)){if(s==='c1kids'){kidsAway();return true;}say([D('Sema','Dürüst tüccarlar Sur\'dan çalmaz.')]);return true;}
  if(C1.minikF&&near(C1.minikF.g.position.x,C1.minikF.g.position.z,1.7)){if(s==='c1kids'){kidsAway();return true;}say([D('Minik','Deniz Abi, bugün gökyüzünden su mu yağdıracaksın?')]);return true;}
  if(near(DOME_IN.x+4.6,DOME_IN.z+4.6,1.5)){if(s==='c1nur'||s==='c1kids'||s==='c1tea'){say([D('Deniz','Önce burada işim var.')]);return true;}if(s==='c1back'){leaveDome(()=>{setQuest('Kafes\'e dön · saat on bire geliyor');MMARK={x:CRANEB.x,z:CRANEB.z,c:'#9ff0c8'};});return true;}if(s==='c1nightgo'){leaveDome(()=>{});return true;}}
