let breathT=0,breathOn=0,beatT=0,last=performance.now(),paused=false;
function togglePause(){if(!playing&&!paused)return;paused=!paused;paused?show('pause'):hide('pause');}
$('bRes').onclick=()=>togglePause();$('bMenu').onclick=()=>{paused=false;hide('pause');playing=false;show('menu');};
$('bStart').onclick=()=>{if(step==='menu')startGame();else if(step==='end')location.reload();else{hide('menu');playing=true;}};
$('bCode').onclick=()=>{const v=($('code').value||'').trim().toLocaleUpperCase('tr-TR').replace(/İ/g,'I');if(v==='FISILTI'&&step==='menu'&&!$('bStart').disabled){audioInit();startCh2(true);resize();}else if(v==='YAMA'&&step==='menu'&&!$('bStart').disabled){audioInit();startCh3(true);resize();}else if(v==='TAHIL'&&(step==='menu'||step==='end')&&!$('bStart').disabled){audioInit();startCh4(true);resize();}else if(v==='KILIT'&&(step==='menu'||step==='end')&&!$('bStart').disabled){audioInit();startCh5(true);resize();}else{$('code').value='';$('code').placeholder='Geçersiz şifre';}};
$('bGfx').onclick=()=>{hiGfx=!hiGfx;$('bGfx').textContent='Grafik: '+(hiGfx?'Yüksek':'Düşük');setGfx();};
$('bSnd').onclick=()=>{sndOn=!sndOn;$('bSnd').textContent='Ses: '+(sndOn?'Açık':'Kapalı');if(master)master.gain.value=sndOn?.8:0;};
function update(dt){const t=performance.now()/1000;
 // MERIDIAN breath every 11s
 breathT+=dt;let frozen=false;if(breathT>11){breathT=0;breathOn=.3;canvas.classList.add('breath');SFX.breath();}
 if(breathOn>0){breathOn-=dt;frozen=true;if(breathOn<=0)canvas.classList.remove('breath');}
 for(let i=MIXERS.length-1;i>=0;i--){const r=MIXERS[i];if(!r.on){MIXERS.splice(i,1);continue;}r.mixer.update(frozen?0:dt);}
 // night lerp
 P.yamaCd=(P.yamaCd||0)-dt;if(ZONE===3){zl(dt);c3update(dt,t);}
 if(ZONE===4){zl(dt);c4update(dt,t);}
 if(ZONE===5){zl(dt);c5update(dt,t);}
 if(ZONE===2){c2update(dt,t);if(HAY.mdl&&HAY.mdl.bones.Spine)HAY.mdl.bones.Spine.rotation.x+=.32;}
 if(ZONE===1){night+=(nightTarget-night)*Math.min(1,dt*.35);scene.fog.color.copy(FOG_DAY).lerp(FOG_NIGHT,night);scene.fog.density=.034+night*.012;hemi.intensity=.55-night*.38;sun.intensity=1.35-night*1.15;sun.color.setHex(night>.5?0x7d9ac8:0xffd29a);}
 if(ZONE===1&&typeof C1!=='undefined'){if(C1.inside==='dome'||C1.inside==='kafes'){scene.fog.color.setHex(0x0a0907);scene.fog.density=.022;}else if(C1.inside==='view'){scene.fog.density=.011;}}
 if(C1.on)c1update(dt,t);
 LAMPS.forEach(l=>{l.L.intensity=(l.base+night*1.4)*(.85+Math.sin(t*13+l.ph)*.08+(Math.random()<.01?-.6:0));});fireL.intensity=1.4+Math.sin(t*9)*.25+Math.random()*.2;
 // ash
 if(!frozen){const a=ash.geometry.attributes.position.array;for(let i=0;i<ASHN;i++){a[i*3+1]-=ashV[i]*dt;a[i*3]+=Math.sin(t*.7+i)*dt*.35+dt*.4;
  if(a[i*3+1]<0){a[i*3+1]=16+Math.random()*3;a[i*3]=P.pos.x+(Math.random()-.5)*50;a[i*3+2]=P.pos.z+(Math.random()-.5)*50;}}ash.geometry.attributes.position.needsUpdate=true;}
 CLOTHES.forEach(c=>{c.rotation.z=Math.sin(t*1.6+c.userData.sw)*.12;});
 ITEMS.forEach(it=>{if(!it.taken&&it.g.visible){it.g.rotation.y+=dt*1.5;it.g.position.y=TOP+(it.type==='part'?.7:.35)+Math.sin(t*2.4+it.x)*.08;
  if(playing&&!dlgActive&&Math.hypot(it.x-P.pos.x,it.z-P.pos.z)<1.1){if(it.type==='part'&&step==='parts')pickPart(it);else if(it.type==='ilac'&&P.hp<P.max){it.taken=true;scene.remove(it.g);const h=Math.min(35,P.max-P.hp);P.hp+=h;dmgText(P.pos,'+'+h,'h');SFX.pick();}}}});
 if(dlgActive)cineZoom+=(1-cineZoom)*Math.min(1,dt*2);else cineZoom+=(0-cineZoom)*Math.min(1,dt*2);
 if(playing&&!dlgActive&&!P.dead){
  // input movement
  let mx=0,mz=0;const fw=new THREE.Vector3(-Math.sin(camYaw),0,-Math.cos(camYaw)),rt=new THREE.Vector3(Math.cos(camYaw),0,-Math.sin(camYaw));
  if(keys.KeyW||keys.ArrowUp){mx+=fw.x;mz+=fw.z;}if(keys.KeyS||keys.ArrowDown){mx-=fw.x;mz-=fw.z;}if(keys.KeyD||keys.ArrowRight){mx+=rt.x;mz+=rt.z;}if(keys.KeyA||keys.ArrowLeft){mx-=rt.x;mz-=rt.z;}
  if(joy.x||joy.y){mx+=rt.x*joy.x-fw.x*joy.y;mz+=rt.z*joy.x-fw.z*joy.y;}
  if(mouseDown){ray.setFromCamera(mouseN,camera);const hp=new THREE.Vector3();if(targetEnemy&&!targetEnemy.dead){}else if(ray.ray.intersectPlane(groundPlane,hp)){moveTarget=hp;}}
  if(mx||mz){moveTarget=null;targetEnemy=null;clickTarget=null;}
  let speed=0;const SP=5.2;
  if(targetEnemy&&!targetEnemy.dead){const dx=targetEnemy.x-P.pos.x,dz=targetEnemy.z-P.pos.z,d=Math.hypot(dx,dz);if(d>1.8){mx=dx/d;mz=dz/d;}else{attack(targetEnemy);if(!mouseDown)targetEnemy=null;}}
  else if(moveTarget){const dx=moveTarget.x-P.pos.x,dz=moveTarget.z-P.pos.z,d=Math.hypot(dx,dz);if(d>.25){mx=dx/d;mz=dz/d;}else moveTarget=null;if(clickTarget&&d<2.4){talkTo(clickTarget);}}
  const ml=Math.hypot(mx,mz);if(ml>0){mx/=ml;mz/=ml;speed=SP*(joy.x||joy.y?Math.min(1,Math.hypot(joy.x,joy.y)*1.3):1);const o={x:P.pos.x,z:P.pos.z};if(!tryMove(o,P.pos.x+mx*speed*dt,P.pos.z+mz*speed*dt,.38)){moveTarget=null;}P.pos.x=o.x;P.pos.z=o.z;P.face=Math.atan2(mx,mz);}
  if(atkHeld&&!C1.on){const e=nearestEnemy(2.6);if(e)attack(e);else if(P.atkCd<=0){P.atkCd=.4;pu.attacking=.3;SFX.swing();if(PM)PM.once('Sword_Slash',2.1);}}
  P.atkCd-=dt;P.comboT-=dt;P.empCd-=dt;P.inv-=dt;P.yuva=Math.min(P.ymax,P.yuva+dt*5);
  animHuman(player,speed,dt);if(PM&&!(pu.attacking>0&&speed<.3))PM.play(speed>4.6?'Run':speed>0.3?'Walk':'Idle',.18);homeArrive();
  // drone
  if(droneOn){droneA+=dt*.16;const cx=14+Math.cos(droneA)*13,cz=Math.sin(droneA*1.3)*13;drone.position.set(cx,TOP+7,cz);drone.rotation.y=-droneA;dT.position.set(cx,TOP,cz);drone.children.forEach((c,i)=>{if(i>0&&i<5)c.rotation.y+=dt*30;});
   alarmCd-=dt;if(Math.hypot(P.pos.x-cx,P.pos.z-cz)<2.4&&alarmCd<=0){alarmCd=16;toast('SUR DRONE\'U SENİ GÖRDÜ',true,2.5);if(sirenG)sirenG.gain.setTargetAtTime(.05,AC.currentTime,.1);setTimeout(()=>sirenG&&sirenG.gain.setTargetAtTime(0,AC.currentTime,.5),4000);
    const spots=[[2,2.5],[-2,-2.5],[2.5,-2],[-2.5,2]];let n=0;for(const [ox,oz] of spots){if(n>=2)break;if(walkable(P.pos.x+ox*2,P.pos.z+oz*2)){const h=hound(P.pos.x+ox*2,P.pos.z+oz*2);h.aggro=true;h.state='chase';n++;}}}}
  // heartbeat
  if(P.hp/P.max<.3){beatT-=dt;if(beatT<=0){beatT=.9;SFX.beat();}}
 }else{animHuman(player,0,dt);if(PM&&!P.down&&!C1.animLock)PM.play('Idle',.3);}
 // player transform
 player.position.copy(P.pos);let df=P.face-player.rotation.y;while(df>Math.PI)df-=Math.PI*2;while(df<-Math.PI)df+=Math.PI*2;player.rotation.y+=df*Math.min(1,dt*14);
 if(PM&&PM.blade)PM.blade.forEach(m=>m.emissiveIntensity+=(.25-m.emissiveIntensity)*Math.min(1,dt*6));
 if(pu.attacking>0){pu.attacking-=dt;const k=pu.attacking/.28;pu.arms[1].rotation.x=-1.8*Math.sin(k*Math.PI)-.3;pu.arms[1].rotation.z=(P.combo===1?.8:-.4)*Math.sin(k*Math.PI);baton.material.emissiveIntensity=2.5*k;}else{pu.attacking=0;pu.arms[1].rotation.z=0;baton.material.emissiveIntensity*=.9;}
 neckL.intensity+=(.8-neckL.intensity)*Math.min(1,dt*4);c1late(dt);updTaziFly(dt,t);
 NPCS.forEach(n=>{n.mesh.userData.hip.position.y=.92+Math.sin(t*1.5+n.x)*.008;});
 updEnemies(dt,frozen);updFX(dt);updDlg(dt);updCamera(dt);
 if(toastT>0){toastT-=dt;if(toastT<=0)$('toast').style.opacity=0;}
 // HUD
 $('hpf').style.width=Math.max(0,P.hp/P.max*100)+'%';$('hpn').textContent=Math.max(0,Math.ceil(P.hp));$('ypf').style.width=(P.yuva/P.ymax*100)+'%';$('ypn').textContent=Math.floor(P.yuva);
 $('cd2').style.height=(yamaUnlocked&&P.yamaCd>0?P.yamaCd/7*100:0)+'%';$('cd1').style.height=(P.empCd>0?P.empCd/4*100:(P.yuva<35?100:0))+'%';$('lvl').textContent='Seviye '+P.lvl;$('xpf').style.width=(P.xp/(80+P.lvl*40)*100)+'%';
 drawMinimap();}
// ================= MINIMAP =================
const mm=$('mm').getContext('2d');
function drawMinimap(){const W=200,s=4.2;mm.fillStyle='#14130f';mm.fillRect(0,0,W,W);mm.save();mm.translate(W/2,W/2);mm.rotate(camYaw);mm.translate(-P.pos.x*s,-P.pos.z*s);
 mm.fillStyle='#6d6650';RECTS.forEach(([x,z,w,d])=>mm.fillRect((x-w/2)*s,(z-d/2)*s,w*s,d*s));mm.fillStyle='#3e3a2e';DOMES.forEach(d=>{mm.beginPath();mm.arc(d.x*s,d.z*s,d.r*s,0,7);mm.fill();});
 if(step==='parts')PARTS.forEach(p=>{if(!p.taken){mm.fillStyle='#ffa040';mm.beginPath();mm.arc(p.x*s,p.z*s,5,0,7);mm.fill();}});
 if(step==='toNur'||step==='back'){mm.fillStyle='#e9d9a8';mm.beginPath();mm.arc(NUR.x*s,NUR.z*s,6,0,7);mm.fill();}
 if(MMARK&&(ZONE!==1||C1.on)){mm.fillStyle=MMARK.c;mm.beginPath();mm.arc(MMARK.x*s,MMARK.z*s,6,0,7);mm.fill();}
 if(step==='night'){mm.fillStyle='#9fe9ff';mm.beginPath();mm.arc(.5*s,-.5*s,6,0,7);mm.fill();}
 mm.fillStyle='#ff3a28';ENEMIES.forEach(e=>{if(!e.dead){mm.beginPath();mm.arc(e.x*s,e.z*s,e.boss?5:3,0,7);mm.fill();}});
 if(droneOn){mm.strokeStyle='rgba(255,230,180,.6)';mm.beginPath();mm.arc(drone.position.x*s,drone.position.z*s,2.4*s,0,7);mm.stroke();}
 mm.restore();mm.save();mm.translate(W/2,W/2);mm.rotate(camYaw-P.face+Math.PI);mm.fillStyle='#f2e6c8';mm.beginPath();mm.moveTo(0,-8);mm.lineTo(5,6);mm.lineTo(-5,6);mm.closePath();mm.fill();mm.restore();}
